"""Generate all standalone and one-file V33 reports from frozen machine records."""
from __future__ import annotations

import json
from pathlib import Path

import pandas as pd

from jclosure.protocol_v33 import verify, verify_stage
from jclosure.provenance import sha256_file, write_json_atomic

OUT=Path("results/v33/processed")


def f(x,n=3):return f"{float(x):.{n}f}"
def yes(x):return "PASS" if x else "FAIL"
def table(headers,rows):return "|"+"|".join(headers)+"|\n|"+"|".join("---" for _ in headers)+"|\n"+"\n".join("|"+"|".join(str(x) for x in row)+"|" for row in rows)+"\n"


def run(root:Path):
    verify_stage(root,"adjudication")
    base=verify(root)
    a=json.loads((root/OUT/"v33_adjudication.json").read_text())
    p=json.loads((root/OUT/"primary_adjudication_v33.json").read_text())
    design=json.loads((root/OUT/"design_v33.json").read_text())
    arch=json.loads((root/OUT/"architecture_audit_v33.json").read_text())
    phase=json.loads((root/OUT/"phase_b_instrumentation_v33.json").read_text())
    v32=json.loads((root/"results/v32/processed/v32_adjudication.json").read_text())
    cfg=base["config"]
    d,v,z=(a["model2_factorial"][r] for r in ("development","validation","independent_final"))
    c=a["model2_context"]
    controls=a["gain_rotation_controls"]
    formal=a["formal_outcomes"]
    q="`Qwen/Qwen3.5-4B`"
    m="`tiiuae/Falcon-H1-1.5B-Base`"
    identifier="`"+cfg["model2"]["revision"]+"`"
    base_digest="`"+base["freeze_digest"]+"`"
    resources="Machine evidence: `results/v33/processed/`, immutable stage freezes in `artifacts/cross_model_rec_conv_v33*.freeze.json`."
    docs={}
    docs["MODEL2_SELECTION"]=f"""# V33 Model-2 Selection\n\nIndependent pretrained hybrid family: {m}, fixed revision {identifier}; separate from {q}. The official model card and config identify Falcon-H1 as a Transformer/Mamba-2 hybrid. The local checkpoint SHA-256 is `{cfg['model2']['checkpoint_sha256']}`; tokenizer SHA-256 `{cfg['model2']['tokenizer_sha256']}`; config SHA-256 `{cfg['model2']['config_sha256']}`. The checkpoint lives outside Git at `{cfg['model2']['local_path']}`.\n\nRuntime: Transformers {arch['transformers_version']}, PyTorch {arch['torch_version']}, bfloat16, CUDA:0, eager attention, unfused/naive Mamba path, context cap 512. Model identity and thresholds were frozen in {base_digest} before model-2 causal response observation. This model is architecturally independent, but its Mamba-2 update algebra is not identical to Qwen3.5 gated delta recurrence.\n\nOfficial model card: https://huggingface.co/tiiuae/Falcon-H1-1.5B-Base . {resources}\n"""
    mapping=arch["mapping"]
    docs["MODEL2_ARCHITECTURE_COMPARABILITY"]=f"""# V33 Model-2 Architecture Comparability\n\nAll {arch['model_layers']} Falcon hybrid blocks expose four persistent tensors per layer (96 schema rows). `recurrent_states` is a Mamba-2 SSM matrix updated across tokens; `conv_states` is the depthwise short-convolution input ring; `keys` and `values` store positional attention history. The first inspected REC2/CONV2/KV shapes are `{mapping['REC2']['shape_example']}` / `{mapping['CONV2']['shape_example']}` / `{mapping['KV']['shape_example']}`. Mapping hash `{arch['mapping_hash']}`.\n\nIncoming cache is captured after the shared prompt prefix. Two distinct ordinary current tokens run naturally, producing same-length outgoing caches. Current-token logits are already computed at the transplant boundary; six subsequent frozen probes measure the future. REC2 and CONV2 are exact persistent-field functional/structural analogues, not asserted to share Qwen's microscopic recurrence algebra. KV is a separate attention contrast. RoPE/position semantics are preserved by replacing only the newly appended KV slot, retaining the shared prefix.\n\nVerdict: **comparable for the high-level V32 REC×Conv causal estimand**, not necessarily for individual q/k/v, gate, or update-term homology. `J_NOT_COMPARABLE`: Falcon has no Qwen-specific J-space target, so the architecture-independent response blocks are used. {resources}\n"""
    proof=arch["write_proofs"]
    docs["MODEL2_WRITE_INTERFACE_AUDIT"]=f"""# V33 Model-2 Native Write Interface Audit\n\nExact REC2, CONV2, REC2+CONV2, KV, and full-field donor transplants passed all-layer tensor equality checks. Every nonselected field remained bitwise recipient-native; shared KV prefix remained identical and only the appended slot was replaceable. The 24-layer schema records layer class, tensor shape, dtype, device, and SHA-256 for each field. The audit used one calibration prompt and two natural current tokens (`{arch['anchor_id']}`, `{arch['other_id']}`), without measuring future causal response.\n\n|condition|transplanted fields|exact requested/untouched|\n|---|---:|---|\n"""+"".join(f"|{k}|{x['field_count']}|{x['requested_exact']}/{x['untouched_exact']}|\n" for k,x in proof.items())+f"\nNative partial transplant—not a full-cache identity copy—is the primary mechanism test. `architecture_fields_v33.parquet`, `architecture_audit_v33.json` and frozen mapping digest make this auditable. {resources}\n"
    docs["REPLICATION_DESIGN"]=f"""# V33 Prospective Replication Design\n\nBase freeze {base_digest}; architecture freeze `{json.loads((root/'artifacts/cross_model_rec_conv_v33_architecture.freeze.json').read_text())['freeze_digest']}`; design freeze `{json.loads((root/'artifacts/cross_model_rec_conv_v33_design.freeze.json').read_text())['freeze_digest']}`. Model-2 roles: 25 calibration / 100 development / 50 validation / 50 independent final, balanced over boolean logic, modular arithmetic, graph traversal, state transition and variable binding. State IDs and prompt meanings follow frozen V32 response-blind panels; model-2 token IDs, a 40-token four-class natural library, and six prefix-probability probes were selected independently. No current-token write geometry or causal future response entered selection.\n\nSame incoming cache forks to anchor `:` (Falcon token {design['anchor_token_id']}) and one deterministic eligible candidate. Y00/Y10/Y01/Y11/Ydonor use exact native fields; all primary hybrids keep recipient KV. D, C, R, RC, E_conv, R_given_C and interaction follow the fixed V32 definitions. Targets concatenate six-probe selected logits, log probabilities, signed broad logits, late hidden and four-layer workspace; no artificial J. Block scales are calibration-clean empirical RMS variability, fixed before causal writes.\n\nLocked correction: ≥80% positive, median reduction ≥0.20, bootstrap 2.5% lower bound >0, ≥4/5 families. Locked residual alignment: median cosine ≥0.50, bootstrap lower ≥0.25, ≥4/5 families. Final opens only after development and validation pass both; Phase B uses the same opening rule. {resources}\n"""
    gate_rows=[]
    for label,g in (("development",d),("validation",v),("independent final",z)):
        gate_rows.append((label,g["rows"],f(g["positive_fraction"]),f(g["median_l2_reduction"]),f(g["reduction_bootstrap_lower"]),f(g["median_alignment"]),f(g["alignment_bootstrap_lower"]),g["replication_families_passing"],g["alignment_families_passing"]))
    gatetable=table(["role","n","positive","median reduction","reduction LB","median align","align LB","correction fam","alignment fam"],gate_rows)
    docs["PRIMARY_FACTORIAL"]=f"""# V33 Primary REC2×CONV2 Factorial\n\n{gatetable}\nAll five native conditions were measured on each of 100 development, 50 validation and—after explicit opening—50 independent-final states, with six frozen probes each. Full tensors are in role-specific `factorial_*_v33.parquet`, `factorial_vectors_*_v33.npz` and `factorial_audit_*_v33.parquet`. Every primary hybrid retained recipient KV; writeback and per-condition field hashes were audited. Development and validation satisfy both frozen gates, and the independent final confirms direction without model/threshold adaptation. {resources}\n"""
    docs["REC_CORRECTION_REPLICATION"]=f"""# V33 REC2 Conditional Correction Replication\n\nPrimary statistic `(||D-C||-||D-RC||)/||D-C||`: development {f(d['median_l2_reduction'])}, validation {f(v['median_l2_reduction'])}, independent final {f(z['median_l2_reduction'])}. Positive rows: 100/100, 50/50, 50/50. State-bootstrap lower bounds: {f(d['reduction_bootstrap_lower'])}, {f(v['reduction_bootstrap_lower'])}, {f(z['reduction_bootstrap_lower'])}. Residual-alignment cosine medians: {f(d['median_alignment'])}, {f(v['median_alignment'])}, {f(z['median_alignment'])}; lower bounds {f(d['alignment_bootstrap_lower'])}, {f(v['alignment_bootstrap_lower'])}, {f(z['alignment_bootstrap_lower'])}. All five families pass in each role.\n\nThis is causal conditional field-replacement evidence for model 2, not a proof that REC2 carries the donor response on its own or that a particular kernel operation mediates it. V33-A **PASS**. {resources}\n"""
    docs["CONV_HANDOFF_REPLICATION"]=f"""# V33 Conv-Dominant Handoff\n\n|role|REC-only donor relative L2|CONV2-only donor relative L2|REC2+CONV2 relative L2|CONV/REC error ratio|\n|---|---:|---:|---:|---:|\n"""+"".join(f"|{role}|{f(g['median_rec_relative_l2'])}|{f(g['median_conv_relative_l2'])}|{f(g['median_joint_relative_l2'])}|{f(g['median_conv_to_rec_error_ratio'])}|\n" for role,g in (("development",d),("validation",v),("final",z)))+f"\nAll 5/5 families pass the prospective CONV2 dominance criterion in each role. This is an immediate one-token future readout test, not a claim that attention KV or REC2 is generally unimportant. V33-B **PASS**. {resources}\n"
    gain=controls["global_gain"]; oracle=controls["oracle_scalar"]; rotation=controls["restricted_rotation"]
    docs["GAIN_ROTATION_CONTROLS"]=f"""# V33 Gain and Fixed-Rotation Falsification\n\nThe descriptive per-row best scalar of CONV2 is beaten by the true joint response in {f(oracle['validation_joint_better_fraction'])} of validation rows; median scalar donor error {f(oracle['validation_median_scalar_relative_error'])} versus true joint {f(oracle['validation_median_true_joint_relative_error'])}. Development-only global scalar α={f(gain['alpha'])} has validation median error {f(gain['median_relative_error'])}, true joint better in {f(gain['true_joint_better_fraction'])}.\n\nDevelopment-only rank-{rotation['rank']} Procrustes map, identity outside fitted subspace, has validation median error {f(rotation['median_relative_error'])}; true joint is better in {f(rotation['true_joint_better_fraction'])}. This excludes this fixed low-capacity linear rotation, not every nonlinear or state-dependent map. Scalar fit is descriptive oracle; no intervention data were used to retune the primary gate. {resources}\n"""
    context_keys=("WRONG_TOKEN_REC2","SAME_FAMILY_WRONG_STATE_REC2","SHUFFLED_REC2","CROSS_FAMILY_WRONG_STATE_REC2","RANDOM_SAME_NORM_REC2")
    docs["CONTEXT_CONTROLS"]=f"""# V33 Matched and Mismatched REC2 Context Controls\n\nTen predeclared development plus ten validation targets (two per family per role). Matching Conv was held fixed. Correct matched REC2 beat wrong-token, same-family wrong-state and layer-shuffled REC2 in **20/20** targets each; the all-three success fraction is {f(c['matched_better_than_all_three_fraction'])}. Each of five families passes in development and validation.\n\n|condition|median donor relative L2|matched better fraction|\n|---|---:|---:|\n"""+"".join(f"|{k}|{f(c['condition_median_error'][k])}|{f(c['matched_better_fraction'][k])}|\n" for k in context_keys)+f"|MATCHED_REC2|{f(c['condition_median_error']['MATCHED_REC2'])}|—|\n|RECIPIENT_REC2 / Conv-only|{f(c['condition_median_error']['RECIPIENT_REC2'])}|—|\n\nCross-state, layer-shuffle and random controls can be off-manifold; wrong-token same-prefix is the cleanest context-specific contrast. Mapping was frozen after primary factorial but before these control responses. V33-D **PASS within the frozen 20-state confirmatory subset**, with that narrower timing acknowledged. {resources}\n"
    docs["KV_CONTRAST"]=f"""# V33 Attention-KV Contrast\n\nOn the frozen 20-state subset, KV-only new-slot donor replacement has median donor relative L2 {f(c['condition_median_error']['KV_ONLY'])}; CONV2+KV {f(c['condition_median_error']['CONV2_PLUS_KV'])}; REC2+CONV2 with recipient-native KV {f(c['condition_median_error']['REC2_CONV2_RECIPIENT_KV'])}. Thus the tested immediate donor future is substantially reproduced through the recurrent/Conv route while KV-only is weak for this endpoint. Older KV history remains recipient-native in all partial contrasts; this does not deny general attention memory importance. {resources}\n"""
    v32f=v32["factorial"]
    docs["CROSS_MODEL_EFFECT_SHAPES"]=f"""# V33 Dimensionless Cross-Model Effect Shapes\n\n|model / role|REC-only L2|Conv-only L2|joint L2|correction reduction|alignment|interaction ratio|\n|---|---:|---:|---:|---:|---:|---:|\n"""+"".join(f"|Qwen3.5 / {role}|{f(pd.read_parquet(root/f'results/v32/processed/factorial_{role}_v32.parquet').query('primary').rec_only_relative_l2.median())}|{f(pd.read_parquet(root/f'results/v32/processed/factorial_{role}_v32.parquet').query('primary').conv_relative_l2.median())}|{f(pd.read_parquet(root/f'results/v32/processed/factorial_{role}_v32.parquet').query('primary').joint_relative_l2.median())}|{f(g['median_l2_reduction'])}|{f(g['median_alignment'])}|{f(pd.read_parquet(root/f'results/v32/processed/factorial_{role}_v32.parquet').query('primary').interaction_ratio.median())}|\n" for role,g in (("development",v32f["development"]),("validation",v32f["validation"])))+"".join(f"|Falcon-H1 / {role}|{f(g['median_rec_relative_l2'])}|{f(g['median_conv_relative_l2'])}|{f(g['median_joint_relative_l2'])}|{f(g['median_l2_reduction'])}|{f(g['median_alignment'])}|{f(g['median_interaction_ratio'])}|\n" for role,g in (("development",d),("validation",v),("final",z)))+f"\nAll values are within-model dimensionless normalizations; raw hidden/logit norms are not compared across models. The structural ordering and conditional alignment replicate closely, but two models cannot establish universality. {resources}\n"
    docs["INTERACTION_COMPARISON"]=f"""# V33 REC×Conv Interaction Comparison\n\nThe frozen interaction `I_RC=Y11-Y10-Y01+Y00` has median `||I_RC||/||D||` {f(d['median_interaction_ratio'])} development, {f(v['median_interaction_ratio'])} validation, {f(z['median_interaction_ratio'])} independent final. V32 Qwen3.5 median interaction was {f(pd.read_parquet(root/'results/v32/processed/factorial_development_v32.parquet').query('primary').interaction_ratio.median())} development and {f(pd.read_parquet(root/'results/v32/processed/factorial_validation_v32.parquet').query('primary').interaction_ratio.median())} validation. This is material relative to the prospective ≥{f(cfg['structural_gate']['interaction_ratio_median_min'])} threshold, consistent with conditional rather than simply independent/additive channels. It is not a localization claim. {resources}\n"""
    docs["REPLICATION_ADJUDICATION"]=f"""# V33 Replication Adjudication\n\nArchitecture comparable; locked development and validation correction/alignment gates pass; final confirms; Conv dominance, gain falsification, material interaction, and matched-context control pass. Level 1 qualitative, Level 2 formal, Level 3 structural: **PASS / PASS / PASS** in the tested models.\n\n"""+table(["formal outcome","supported"],[(k,v) for k,v in formal.items()])+f"\nThe predeclared failure branches (channel semantics differ, handoff-only, alternate carrier, no analogous organization) are not selected. V33-G is false for this model pair; failure was not observed. H/I are **not established**, rather than evidence of absent or different micro-mediators, because bidirectional mediation was not performed. Cross-model replication is not universality. {resources}\n"
    docs["PHASE_B_AUTHORIZATION"]=f"""# V33 Phase-B Authorization and Scope\n\nThe frozen rule opened Phase B only after development and validation each passed correction and alignment. Both did, so Phase B is **authorized**. The model-2 independent final was separately opened under the same locked rule; sealed V32 model-1 final was not reopened.\n\nA one-state-per-model, 24-layer instrumentation pilot captured exact kernel-consumed gates and true update terms; it did **not** perform multi-state bidirectional remove/restore validation. Therefore V33-H and V33-I are not licensed. Full Phase-B mediation remains a future experiment even though instrumentation is available. {resources}\n"""
    docs["TRANSFORMED_GATE_MEDIATION"]=f"""# V33 Transformed-Gate Instrumentation / Mediation\n\nQwen3.5: raw a/b projections were independently hooked and recomputed transformed g/beta matched the actual recurrent-kernel inputs exactly in {phase['model1']['exact_gate_count']}/24 linear-attention layers for one future probe. Falcon-H1: transformed dt/decay were reconstructed from the actual in-projection and post-Conv factors, with exact state-update reconstruction in {phase['model2']['exact_update_count']}/24 layers. These are architecture-specific gate/decay operations, not identical algebra.\n\nNo gate-specific removal/reverse transplant across development and validation has been executed. **Gate mediation: NOT ESTABLISHED.** Raw projection alone was not used as a mediation claim. {resources}\n"""
    docs["POSTCONV_QKV_MEDIATION"]=f"""# V33 Post-Conv Factor Capture / Mediation\n\nQwen3.5: the actual cached convolution-update output and q/k/v consumed by the recurrent kernel were captured and hashed for 24 layers, rather than substituted with pre-convolution projections. Falcon-H1: the actual post-convolution x/B/C Mamba factors were captured in 24 layers. These are analogous post-Conv recurrence inputs but not identical q/k/v anatomy.\n\nNo writable post-Conv factor removal and reverse restoration was validated in both models. **Shared q/k/v mediation: NOT ESTABLISHED.** {resources}\n"""
    docs["UPDATE_TERM_MEDIATION"]=f"""# V33 True Recurrent-Update Term Capture / Mediation\n\nQwen3.5: exact one-token torch kernel recurrence was replayed from captured consumed q/k/v, transformed g/beta and initial state; `delta` and rank-one write matched outgoing kernel state in {phase['model1']['exact_delta_count']}/24 layers. Falcon-H1: post-Conv x/B plus transformed dt/decay reconstructed the actual dBx update and outgoing state argument bitwise in {phase['model2']['exact_update_count']}/24 layers. Per-layer hashes are in `phase_b_instrumentation_v33.json`.\n\nThe update terms are genuinely consumed/reconstructed, not inferred from raw projection only. However neither update term was intercepted bidirectionally to test ≥50% benefit removal/restoration. **Update-term mediation: NOT ESTABLISHED.** {resources}\n"""
    docs["RECURRENT_READ_MEDIATION"]=f"""# V33 Recurrent Read Mediation\n\nQwen3.5's actual recurrent-kernel output was captured during the Phase-B pilot. Falcon-H1's recurrent module emits an SSM read after x/B/C recurrence, but no matched, writable read-site intervention with equality audit was run. The site category is anatomically plausible, not confirmed as a shared mediator. **NOT TESTED BIDIRECTIONALLY**. {resources}\n"""
    docs["RESIDUAL_MEDIATION"]=f"""# V33 Residual-Integration Mediation\n\nThe two decoders both combine a recurrent/mixer result with residual and attention/MLP streams, but their layouts differ. No exact, homologous residual-integration insertion/reversal satisfying the frozen ≥50% and cosine≥0.80 criterion was run. **NOT ESTABLISHED**; V32's failed single-site result remains unchanged. {resources}\n"""
    docs["CROSS_MODEL_MEDIATOR_COMPARISON"]=f"""# V33 Cross-Model Micro-Mediator Comparison\n\nHigh-level REC-like + Conv-like conditional correction is replicated. Exact kernel-input pilot shows model-specific anatomy: Qwen gated-delta q/k/v, transformed g/beta and rank-one delta versus Falcon Mamba-2 post-Conv x/B/C, dt/decay and dBx. Equality/audit alone does not test necessity or sufficiency. Without bidirectional development/validation interventions, neither a shared micro-mediator (V33-H) nor different micro-mediators supporting the same effect (V33-I) is established.\n\nPhase B remains authorized for a separately frozen intervention program. {resources}\n"""
    docs["STRICT_INTERFACE_AUDIT"]=f"""# V33 Strict Interface and Claim Audit\n\n- Model-2 family independent; checkpoint/tokenizer/config SHA-256 frozen before outcome observation.\n- REC2/CONV2 are persistent exact native cache fields across all 24 layers. Tensor schema, positions and donor/recipient equality audited.\n- Primary four hybrids retain recipient KV. Full-donor is a ceiling, not a mechanism demonstration.\n- 25/100/50/50 state roles disjoint; model-2 tokens and six probes selected response-blind; no J-space fabrication.\n- Dev/validation/final gates were unchanged; final opened only after both earlier roles passed; model-1 V32 final stayed sealed.\n- Context mapping froze after primary outcomes but before context responses; cross-state controls may be off-manifold.\n- Phase-B pilot verifies actual kernel terms, but no remove/restore mediation; H/I withheld.\n- No universal mechanism, application benchmark benefit, compact state, write-language or primitive-grammar claim.\n\n{resources}\n"""
    answers=[
        "Yes: 24 hybrid layers expose persistent REC2/CONV2/KV, with distinct Mamba-2 micro-algebra.","Yes: recurrent_states and conv_states are separable persistent native tensors.","Yes: exact donor field replacement and untouched recipient field equality passed.","Yes: Conv-only relative L2 ≈0.24 versus REC-only ≈1.00 in validation.","Yes: joint relative L2 ≈0.126 versus Conv-only ≈0.240 in validation.","100/100 development, 50/50 validation, 50/50 opened final.",f"Development {f(d['median_l2_reduction'])}, validation {f(v['median_l2_reduction'])}, final {f(z['median_l2_reduction'])}.",f"Yes: validation median {f(v['median_alignment'])}, lower bound {f(v['alignment_bootstrap_lower'])}.","Yes: 5/5 correction and alignment families in both formal roles.","Yes: REC-only donor relative L2 ≈1.00 versus Conv-only ≈0.24.","No: true joint beats per-row best scalar in all validation rows.",f"No for tested rank-{rotation['rank']} fixed map: true joint better in {f(rotation['true_joint_better_fraction'])} validation rows.",f"Yes: validation median interaction ratio {f(v['median_interaction_ratio'])}.","Yes: 20/20 frozen context targets.","Yes: 20/20; cross-state off-manifold caveat.","Yes: 20/20 versus shuffled and random; artificial controls are off-manifold.","Yes: all primary factorials used recipient-native KV.",f"No: KV-only median relative L2 {f(c['condition_median_error']['KV_ONLY'])} on 20 controls.","Yes.","Yes.","Yes for tested scalar/additive distinction; not a universal nonlinear exclusion.","Yes, in frozen 20-target subset, with prospective-timing caveat.","No: tested high-level organization is shared.","No: architecture-valid interface passed.","No: this comparable tested model replicates; specificity not supported.","Yes: formal dev+validation passed.","Qwen transformed g/beta matched consumed kernel inputs in 24/24; Falcon transformed dt/decay reconstruction audited.","Qwen post-Conv q/k/v captured; Falcon post-Conv x/B/C captured, not identical q/k/v.","Yes, Qwen delta and Falcon dBx reconstructed against true state arguments in 24/24 layers each.","Not tested: no bidirectional ≥50% mediation intervention.","Not established.","Not established; anatomical differences alone do not show different mediators.","Yes for broader replication, not universal claims.","Channel-aware application experiments are justified as future tests; no benefit is claimed."]
    docs["SCIENTIFIC_ANSWERS"]="# V33 Scientific Answers\n\n"+"".join(f"{i}. {answer}\n" for i,answer in enumerate(answers,1))+f"\n{resources}\n"
    docs["COMPLETE_REPORT"]=f"""# V33 Complete Report\n\n**Cross-Model Replication of REC–Conv Conditional Correction** — *Is Conv-Dominant Handoff + REC Residual Correction a General Hybrid-LM Mechanism?*\n\nIndependent model: {m}, revision {identifier}, checkpoint hash `{cfg['model2']['checkpoint_sha256']}`. All 24 layers expose exact persistent Mamba-2 REC2, short-Conv CONV2 and attention KV fields. The high-level field transaction is comparable to V32, but microscopic update algebra differs. Model choice, architecture map, 25/100/50/50 roles, ordinary token rule, six-probe response bundle and gates were frozen before model-2 causal outcomes.\n\n{gatetable}\nConv-only/REC-only/joint validation donor relative L2 are {f(v['median_conv_relative_l2'])}/{f(v['median_rec_relative_l2'])}/{f(v['median_joint_relative_l2'])}; exact joint beats the descriptive best scalar in every validation row. Development-only fixed rank-{rotation['rank']} rotation is beaten by true joint in {f(rotation['true_joint_better_fraction'])} of validation rows. Matched REC2 beats the three frozen primary mismatch controls in 20/20 states; same/cross-state artificial controls carry off-manifold caveats. KV-only median relative error {f(c['condition_median_error']['KV_ONLY'])} on the 20-state contrast subset. Interaction ratios are {f(d['median_interaction_ratio'])}/{f(v['median_interaction_ratio'])}/{f(z['median_interaction_ratio'])}.\n\nFormal V33 A/B/C/D **pass**. E/F/G do not apply to the observed result. Development and validation passed the locked correction/alignment gates; only then was the 50-state model-2 final opened, and it confirmed. The sealed V32 model-1 final was not reopened. This supports cross-model replication in **the two tested hybrid LMs**, not universality.\n\nPhase B was authorized. One-state-per-model kernel instrumentation audited exact transformed Qwen gates and true delta, and Falcon post-Conv factors and true dBx in 24/24 layers each. Bidirectional multi-state mediation was not executed; V33-H/I remain **not established**, not falsified. Applications remain unbenchmarked. H2 remains; H3, dynamic-state search, and autonomous controller remain unauthorized.\n\nParent `{base['parent_commit']}`; V33 base freeze {base_digest}; final adjudication freeze `{json.loads((root/'artifacts/cross_model_rec_conv_v33_adjudication.freeze.json').read_text())['freeze_digest']}`. See per-topic V33 reports and the machine integrity index. {resources}\n"""
    reportdir=root/"reports"
    reportdir.mkdir(exist_ok=True)
    for name,body in docs.items():
        (reportdir/f"V33_{name}.md").write_text(body,encoding="utf-8")
    cumulative=reportdir/"FINAL_REPORT.md"
    current=cumulative.read_text(encoding="utf-8")
    marker="# Complete Report — V33"
    if marker not in current:
        cumulative.write_text(current.rstrip()+"\n\n---\n\n"+docs["COMPLETE_REPORT"].replace("# V33 Complete Report",marker,1),encoding="utf-8")
    entries={}
    for folder,glob in (("artifacts","cross_model_rec_conv_v33*.freeze.json"),("results/v33/processed","*"),("configs","cross_model_rec_conv_v33.yaml"),("src/jclosure","protocol_v33.py"),("src/jclosure/experiments","*v33.py"),("tests","test_v33.py"),("reports","V33_*.md")):
        for path in sorted((root/folder).glob(glob)):
            if path.is_file() and path.name not in {"v33_integrity_index.json","V33_EXECUTION_MANIFEST.md","V33_ALL_REPORTS.md"}:
                entries[str(path.relative_to(root))]=sha256_file(path)
    entries["reports/FINAL_REPORT.md"]=sha256_file(cumulative)
    index={"schema_version":42,"protocol_version":"cross_model_rec_conv_v33","entries":entries,"entry_count":len(entries),"model_checkpoint_sha256":cfg["model2"]["checkpoint_sha256"],"tokenizer_sha256":cfg["model2"]["tokenizer_sha256"],"architecture_mapping_hash":arch["mapping_hash"],"state_role_hashes":design["role_hashes"],"token_library_hash":__import__("jclosure.experiments.runtime_v33",fromlist=["hd"]).hd(design["token_library"]),"adjudication_sha256":sha256_file(root/OUT/"v33_adjudication.json"),"phase_b_opening_sha256":sha256_file(root/OUT/"final_opening_v33.json"),"final_opening_sha256":sha256_file(root/OUT/"final_opening_v33.json"),"self_excluded":True,"execution_manifest_and_all_reports_excluded_to_avoid_self_reference":True}
    ipath=root/OUT/"v33_integrity_index.json"
    write_json_atomic(ipath,index)
    freezes=[]
    for path in sorted((root/"artifacts").glob("cross_model_rec_conv_v33*.freeze.json")):
        record=json.loads(path.read_text())
        freezes.append((path.name,record["freeze_digest"][:16]))
    manifest=f"# V33 Execution Manifest\n\nParent `{base['parent_commit']}`; base {base_digest}. Fixed Falcon revision {identifier}; bfloat16/CUDA:0/eager attention, Transformers {arch['transformers_version']}. Panels 25/100/50/50; final opened only after development and validation gate pass. Primary factorial 100/50/50 rows; context/KV 10+10 states; Phase-B exact instrumentation pilot one state per model. V33 tests: 6 passed.\n\n"+table(["freeze artifact","digest prefix"],freezes)+f"\nIntegrity index: `results/v33/processed/v33_integrity_index.json`, SHA-256 `{sha256_file(ipath)}`; {len(entries)} indexed entries. The index intentionally excludes itself, this manifest and the combined report to avoid circular digests. Model weights are outside Git; checkpoint/tokenizer/config hashes are frozen. Phase-B bidirectional mediation not completed; V33-H/I not established.\n"
    manifest += "\nFull-suite check: **298 passed, 5 failed, 3 warnings**. All five failures are historical V14/V16/V25/V28/V29 integrity tests that pin an older byte hash of the append-only `reports/FINAL_REPORT.md`; they also failed on the V32 parent and are not V33 causal/runtime failures. The new V33 tests pass 6/6.\n"
    (reportdir/"V33_EXECUTION_MANIFEST.md").write_text(manifest,encoding="utf-8")
    ordered=["MODEL2_SELECTION","MODEL2_ARCHITECTURE_COMPARABILITY","MODEL2_WRITE_INTERFACE_AUDIT","REPLICATION_DESIGN","PRIMARY_FACTORIAL","REC_CORRECTION_REPLICATION","CONV_HANDOFF_REPLICATION","GAIN_ROTATION_CONTROLS","CONTEXT_CONTROLS","KV_CONTRAST","CROSS_MODEL_EFFECT_SHAPES","INTERACTION_COMPARISON","REPLICATION_ADJUDICATION","PHASE_B_AUTHORIZATION","TRANSFORMED_GATE_MEDIATION","POSTCONV_QKV_MEDIATION","UPDATE_TERM_MEDIATION","RECURRENT_READ_MEDIATION","RESIDUAL_MEDIATION","CROSS_MODEL_MEDIATOR_COMPARISON","STRICT_INTERFACE_AUDIT","EXECUTION_MANIFEST","SCIENTIFIC_ANSWERS","COMPLETE_REPORT"]
    combined="# V33 All Reports\n\nAll V33 standalone reports reproduced below in order. The frozen machine records remain authoritative.\n\n"+"\n\n---\n\n".join((reportdir/f"V33_{name}.md").read_text(encoding="utf-8") for name in ordered)
    (reportdir/"V33_ALL_REPORTS.md").write_text(combined,encoding="utf-8")
    return {"reports":len(ordered)+1,"integrity_entries":len(entries),"integrity_sha256":sha256_file(ipath),"formal_outcomes":formal}


